13	
14	// 本文件保护“打开本地数据”时对样品编号唯一性的核对：
15	// 样品编号在本地 samples 样品集合中只能出现一次。JSON 反序列化进 map 时同键的
16	// 后一条记录会悄悄覆盖前一条，已确认的超标结论可能被另一条同编号达标结论替换，
17	// 而逐份完整性校验只能看到幸存条目；因此 Open 必须在逐份校验之前按文件中的原始
18	// JSON 标记核对样品集合的键。即使两条记录内容完全相同也算重复，不按排列顺序择一；
19	// 待判定、已确认、已作废样品一律适用；同一编号一处直接写出、另一处写成 Unicode
20	// 转义仍是重复，中间隔着其他样品也一样。发现重复时整次 Open 失败：
21	// errors.Is(err, ErrCorruptRecord)、返回 nil 存放、错误信息指出重复编号并说明
22	// 样品集合中存在重复编号（区别于同一份样品内部测量项目重复），原文件字节不变。
23	// 不同样品各含同一测量项目是正常数据，空样品集合照常打开。
24	
25	// assertOpenRejectsDuplicateSampleID 断言打开因样品集合内编号重复而整次失败：
26	// nil 存放、ErrCorruptRecord、信息点名重复编号并说明样品集合中存在重复编号，
27	// 且与“同一份样品内部测量项目重复”的错误信息可区分；原文件字节不变。
28	func assertOpenRejectsDuplicateSampleID(t *testing.T, dir, sampleID string) {
29		t.Helper()
30		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
31		if err != nil {
32			t.Fatalf("read file before open: %v", err)
33		}
34		got, err := Open(dir)
35		if err == nil {
36			if got != nil {
37				got.Close()
38			}
39			t.Fatalf("样品集合内编号 %s 重复必须让整次 Open 失败", sampleID)
40		}
41		if got != nil {
42			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
43		}
44		if !errors.Is(err, ErrCorruptRecord) {
45			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
46		}
47		msg := err.Error()
48		if !strings.Contains(msg, sampleID) {
49			t.Fatalf("错误信息应指出重复的样品编号 %q，实际 %q", sampleID, msg)
50		}
51		if !strings.Contains(msg, "样品集合") || !strings.Contains(msg, "重复") {
52			t.Fatalf("错误信息应说明样品集合中存在重复编号，实际 %q", msg)
53		}
54		if !strings.Contains(msg, "样品集合中存在重复的样品编号") {
55			t.Fatalf("错误信息应明确为样品集合内编号重复，实际 %q", msg)
56		}
57		// 与“同一份样品内部测量项目重复”的区分由两条措辞的直接对比在
58		// TestOpenDuplicateSampleIDMessageDistinctFromDuplicateItem 中验证。
59		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
60		if rerr != nil {
61			t.Fatalf("read file after open: %v", rerr)
62		}
63		if string(after) != string(before) {
64			t.Fatalf("打开失败不得覆盖或改写原数据文件")
65		}
66	}
67	
68	// writeRawDataFile 直接写入原始 JSON，用于构造 Go map 无法表达的重复键文件。
69	func writeRawDataFile(t *testing.T, dir, raw string) {
70		t.Helper()
71		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), []byte(raw), 0o644); err != nil {
72			t.Fatalf("write data file: %v", err)
73		}
74	}
75	
76	func sampleObjectJSON(t *testing.T, smp *Sample) string {
77		t.Helper()
78		b, err := json.Marshal(smp)
79		if err != nil {
80			t.Fatalf("marshal sample: %v", err)
81		}
82		return string(b)
83	}
84	
85	// rawEntry 拼出一条 samples 集合条目，keyText 是文件中的原始键标记，
86	// 例如 strconv.Quote("S1") 或字面量 `"S1"`。
87	func rawEntry(t *testing.T, keyText string, smp *Sample) string {
88		t.Helper()
89		return keyText + ":" + sampleObjectJSON(t, smp)
90	}
91	
92	func rawStoreWithEntries(t *testing.T, entries []string) string {
93		t.Helper()
94		pts, err := json.Marshal(openPoints())
95		if err != nil {
96			t.Fatalf("marshal points: %v", err)
97		}
98		return fmt.Sprintf(`{"points":%s,"samples":{%s}}`, pts, strings.Join(entries, ","))
99	}
100	
101	// dupExceededS1：pH 测量值 9、上限 8、已确认超标。
102	func dupExceededS1() *Sample {
103		return &Sample{
104			ID: "S1", PointID: "P1", SampledAt: at(10, 0),
105			Measurements: []Measurement{{Item: openPH, Value: 9}},
106			Status:       StatusConfirmed, Exceeded: true,
107			Results: []ItemResult{
108				{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
109			},
110		}
111	}
112	
113	// dupCompliantS1：同一采样点、同一采样时间，pH 测量值 7、上限 8、已确认达标。
114	func dupCompliantS1() *Sample {
115		return &Sample{
116			ID: "S1", PointID: "P1", SampledAt: at(10, 0),
117			Measurements: []Measurement{{Item: openPH, Value: 7}},
118			Status:       StatusConfirmed, Exceeded: false,
119			Results: []ItemResult{
120				{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
121			},
122		}
123	}
124	
125	// 任务中的核心场景：同一点同一时刻的 S1 先存已确认超标（9 > 8），后一条 S1
126	// 存已确认达标（7 ≤ 8），中间还隔着另一份样品。不能按排列顺序把后一条当成
127	// “最近有效结果”返回：整次打开失败、nil 存放，且最近结果查询无从进行。
128	func TestOpenDuplicateSampleIDExceededThenCompliant(t *testing.T) {
129		dir := t.TempDir()
130		other := &Sample{
131			ID: "S-OTHER", PointID: "P1", SampledAt: at(11, 0),
132			Measurements: []Measurement{{Item: openPH, Value: 5}},
133			Status:       StatusPending,
134		}
135		raw := rawStoreWithEntries(t, []string{
136			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
137			rawEntry(t, strconv.Quote("S-OTHER"), other),
138			rawEntry(t, strconv.Quote("S1"), dupCompliantS1()),
139		})
140		writeRawDataFile(t, dir, raw)
141		assertOpenRejectsDuplicateSampleID(t, dir, "S1")
142	
143		// 不能留下任何内部状态：修正成只保留超标那一条后，同目录即可正常打开，
144		// 且读回的是超标结论（证明此前没有悄悄读入达标版本）。
145		writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
146			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
147			rawEntry(t, strconv.Quote("S-OTHER"), other),
148		}))
149		s, err := Open(dir)
150		if err != nil {
151			t.Fatalf("去除重复编号后应正常打开: %v", err)
152		}
153		defer s.Close()
154		latest, ok, err := s.LatestResult("P1")
155		if err != nil || !ok || latest.ID != "S1" {
156			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
157		}
158		if !latest.Exceeded || latest.Results[0].Value != 9 || latest.Results[0].Limit != 8 {
159			t.Fatalf("已确认的超标依据必须原样保留: %+v", latest)
160		}
161	}
162	
163	// 即使两条重复记录内容完全相同，也按重复编号拒绝：不能合并、不能择一返回。
164	func TestOpenDuplicateSampleIDIdenticalRecords(t *testing.T) {
165		dir := t.TempDir()
166		raw := rawStoreWithEntries(t, []string{
167			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
168			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
169		})
170		writeRawDataFile(t, dir, raw)
171		assertOpenRejectsDuplicateSampleID(t, dir, "S1")
172	}
173	
174	// 编号是否相同按 JSON 解码后的完整文本判断：一处直接写 "S1"，另一处把 S 写成
175	// Unicode 转义（"S1" 解码后仍是 S1），必须识别为重复。
176	func TestOpenDuplicateSampleIDUnicodeEscape(t *testing.T) {
177		dir := t.TempDir()
178		raw := rawStoreWithEntries(t, []string{
179			rawEntry(t, `"S1"`, dupExceededS1()),
180			// 文件中的原始键标记是 Unicode 转义写出的 S（\u0053）加字面量 1，
181			// 而不是直接的 S1；Go 原始字符串字面量里反斜杠按原样落盘。
182			rawEntry(t, `"\u00531"`, dupCompliantS1()),
183		})
184		writeRawDataFile(t, dir, raw)
185		assertOpenRejectsDuplicateSampleID(t, dir, "S1")
186	}
187	
188	// 重复不依赖两条记录相邻：S1、S2 之后再次出现 S1，仍要识别。
189	func TestOpenDuplicateSampleIDNonAdjacent(t *testing.T) {
190		dir := t.TempDir()
191		s2 := &Sample{
192			ID: "S2", PointID: "P1", SampledAt: at(11, 0),
193			Measurements: []Measurement{{Item: openPH, Value: 5}},
194			Status:       StatusPending,
195		}
196		raw := rawStoreWithEntries(t, []string{
197			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
198			rawEntry(t, strconv.Quote("S2"), s2),
199			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
200		})
201		writeRawDataFile(t, dir, raw)
202		assertOpenRejectsDuplicateSampleID(t, dir, "S1")
203	}
204	
205	// 唯一性要求对任何状态的样品都生效，不以是否已有判定结果为条件。
206	func TestOpenDuplicateSampleIDAppliesToAllStatuses(t *testing.T) {
207		cases := []struct {
208			name   string
209			status Status
210		}{
211			{"待判定", StatusPending},
212			{"已确认", StatusConfirmed},
213			{"已作废", StatusVoided},
214		}
215		for _, c := range cases {
216			t.Run(c.name, func(t *testing.T) {
217				dir := t.TempDir()
218				smp := &Sample{
219					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
220					Measurements: []Measurement{{Item: openPH, Value: 9}},
221					Status:       c.status,
222				}
223				if c.status == StatusConfirmed {
224					smp.Exceeded = true
225					smp.Results = []ItemResult{
226						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
227					}
228				}
229				if c.status == StatusVoided {
230					smp.VoidReason = "录入信息有误"
231				}
232				raw := rawStoreWithEntries(t, []string{
233					rawEntry(t, strconv.Quote("S1"), smp),
234					rawEntry(t, strconv.Quote("S1"), smp),
235				})
236				writeRawDataFile(t, dir, raw)
237				assertOpenRejectsDuplicateSampleID(t, dir, "S1")
238			})
239		}
240	}
241	
242	// 文件里其他样品再正常，也不能只读入正常部分：重复编号让整次打开失败，
243	// 正常样品也读不到。
244	func TestOpenDuplicateSampleIDRejectsWholeFile(t *testing.T) {
245		dir := t.TempDir()
246		good := &Sample{
247			ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
248			Measurements: []Measurement{{Item: openPH, Value: 7}},
249			Status:       StatusConfirmed, Exceeded: false,
250			Results: []ItemResult{
251				{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
252			},
253		}
254		raw := rawStoreWithEntries(t, []string{
255			rawEntry(t, strconv.Quote("S-GOOD"), good),
256			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
257			rawEntry(t, strconv.Quote("S1"), dupCompliantS1()),
258		})
259		writeRawDataFile(t, dir, raw)
260		assertOpenRejectsDuplicateSampleID(t, dir, "S1")
261	}
262	
263	// 样品集合内编号重复的错误信息必须能与同一份样品内部测量项目重复区分开。
264	func TestOpenDuplicateSampleIDMessageDistinctFromDuplicateItem(t *testing.T) {
265		dir := t.TempDir()
266	
267		// 样品集合层：两个 S1。
268		writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
269			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
270			rawEntry(t, strconv.Quote("S1"), dupExceededS1()),
271		}))
272		_, err := Open(dir)
273		if !errors.Is(err, ErrCorruptRecord) {
274			t.Fatalf("编号重复应返回 ErrCorruptRecord，got %v", err)
275		}
276		idMsg := err.Error()
277		if !strings.Contains(idMsg, "样品集合中存在重复的样品编号") {
278			t.Fatalf("编号重复应说明样品集合中存在重复编号，实际 %q", idMsg)
279		}
280	
281		// 单份样品内部：measurements 里 pH 出现两次，只有一个 S1。
282		within := &Sample{
283			ID: "S1", PointID: "P1", SampledAt: at(10, 0),
284			Measurements: []Measurement{{Item: openPH, Value: 9}, {Item: openPH, Value: 7}},
285			Status:       StatusPending,
286		}
287		writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
288			rawEntry(t, strconv.Quote("S1"), within),
289		}))
290		_, err = Open(dir)
291		if !errors.Is(err, ErrCorruptRecord) {
292			t.Fatalf("测量项目重复应返回 ErrCorruptRecord，got %v", err)
293		}
294		itemMsg := err.Error()
295		if !strings.Contains(itemMsg, "测量项目") {
296			t.Fatalf("测量项目重复应点名测量项目，实际 %q", itemMsg)
297		}
298		if strings.Contains(itemMsg, "样品集合中存在重复的样品编号") {
299			t.Fatalf("测量项目重复不应报成样品集合内编号重复，实际 %q", itemMsg)
300		}
301	}
302	
303	// 不同样品都包含 pH（或各自包含同名字段）是正常数据，不能误判为编号重复。
304	func TestOpenSameItemAcrossSamplesIsNotDuplicateID(t *testing.T) {
305		dir := t.TempDir()
306		a := &Sample{
307			ID: "S1", PointID: "P1", SampledAt: at(10, 0),
308			Measurements: []Measurement{{Item: openPH, Value: 9}},
309			Status:       StatusPending,
310		}
311		b := &Sample{
312			ID: "S2", PointID: "P1", SampledAt: at(11, 0),
313			Measurements: []Measurement{{Item: openPH, Value: 7}},
314			Status:       StatusPending,
315		}
316		writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
317			rawEntry(t, strconv.Quote("S1"), a),
318			rawEntry(t, strconv.Quote("S2"), b),
319		}))
320		s, err := Open(dir)
321		if err != nil {
322			t.Fatalf("不同样品各含 pH 是正常数据: %v", err)
323		}
324		defer s.Close()
325		if list, err := s.ListByPoint("P1"); err != nil || len(list) != 2 {
326			t.Fatalf("两份不同编号的样品都应读入: %+v err=%v", list, err)
327		}
328	}
329	
330	// 同一份样品记录内部出现重名键（这里重复写 id），不是样品集合层的编号重复：
331	// 扫描必须跳过整条记录值，不把记录内部字段当成样品编号统计。
332	func TestOpenDuplicateKeyInsideSampleRecordIsNotDuplicateID(t *testing.T) {
333		dir := t.TempDir()
334		smp := &Sample{
335			ID: "S1", PointID: "P1", SampledAt: at(10, 0),
336			Measurements: []Measurement{{Item: openPH, Value: 9}},
337			Status:       StatusPending,
338		}
339		obj := sampleObjectJSON(t, smp)
340		// 去掉末尾 '}'，再补一个同值的重复 id 字段。
341		obj = obj[:len(obj)-1] + `,"id":"S1"}`
342		writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
343			`"S1":` + obj,
344		}))
345		s, err := Open(dir)
346		if err != nil {
347			t.Fatalf("记录内部重名键不是样品编号重复，其余内容完整时应正常读入: %v", err)
348		}
349		defer s.Close()
350		if list, err := s.ListByPoint("P1"); err != nil || len(list) != 1 || list[0].ID != "S1" {
351			t.Fatalf("样品应正常读入: %+v err=%v", list, err)
352		}
353	}
354	
355	// 空样品集合继续照常打开。
356	func TestOpenEmptySamplesNotDuplicateID(t *testing.T) {
357		dir := t.TempDir()
358		writeDiskFile(t, dir, diskState{
359			Points:  openPoints(),
360			Samples: map[string]*Sample{},
361		})
362		s, err := Open(dir)
363		if err != nil {
364			t.Fatalf("空样品集合应正常打开: %v", err)
365		}
366		defer s.Close()
367	}
368	
369	// 正常录入的幂等行为不因这次修复改变：同编号同内容返回原样品；
370	// 编号相同但内容不同仍由录入接口整体拒绝（不在打开阶段处理正常流程文件）。
371	func TestOpenResubmitBehaviorUnchangedAfterDuplicateIDFix(t *testing.T) {
372		s, dir := open(t)
373		mustPoint(t, s, "P1", "一号取水口")
374		first := mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
375		again, err := s.SubmitSample("S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
376		if err != nil || again.ID != first.ID {
377			t.Fatalf("同编号同内容应返回原样品: %+v err=%v", again, err)
378		}
379		if _, err := s.SubmitSample("S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 7}); !errors.Is(err, ErrSampleConflict) {
380			t.Fatalf("同编号内容不同仍应整体拒绝 ErrSampleConflict，got %v", err)
381		}
382		if err := s.Close(); err != nil {
383			t.Fatalf("Close: %v", err)
384		}
385	
386		// 正常流程保存的文件重新打开不受影响。
387		s2, err := Open(dir)
388		if err != nil {
389			t.Fatalf("正常流程保存的文件应正常打开: %v", err)
390		}
391		defer s2.Close()
392		if list, err := s2.ListByPoint("P1"); err != nil || len(list) != 1 || list[0].ID != "S1" {
393			t.Fatalf("重开后应看到原样品: %+v err=%v", list, err)
394		}
395	}
