input.new_string:
// samplesFieldName 是顶层样品集合字段在 JSON 中的规范名称；读取时按
// ASCII 大小写不敏感的方式识别（asciiEqualFold），刻意与 encoding/json 的
// foldName 对全 ASCII 标签的匹配规则保持一致：samples、Samples、SAMPLES
// 以及把字母写成 Unicode 转义（解码后仍是同一 ASCII 文本）的写法都会被当作
// 同一个样品集合字段；而像 "ſamples"（长 s，U+017F）这类只在 Unicode 全角
// 折叠下才等价的键不会被 json 读进 Samples，也不纳入核对，避免把 json 本会
// 忽略的未知字段误判成样品集合。sample、x-samples 等其他字段名同样不在此列。
const samplesFieldName = "samples"

// asciiEqualFold 判断 s 是否与全 ASCII 的 lower（全部为小写 ASCII 字母）
// 在仅折叠 ASCII 大小写的规则下相等，规则与 encoding/json 匹配结构体字段标签
// 时所用的 foldName 对 ASCII 标签的判定一致：长度必须相同，s 中的 A-Z 折成
// 小写后逐字节相等；非 ASCII 字符一律不与 ASCII 字母折叠。
func asciiEqualFold(s, lower string) bool {
	if len(s) != len(lower) {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= 'A' && c <= 'Z' {
			c += 'a' - 'A'
		}
		if c != lower[i] {
			return false
		}
	}
	return true
}

